"""Regenerate the browser-safe sample bundle from the canonical Python samples."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "backend"))
from app.nlp.samples import SAMPLE_CONTRACTS  # noqa: E402

out = ROOT / "frontend" / "src" / "staticSamples.js"
out.write_text(
    "// Generated by scripts/export_static_samples.py; source of truth: backend/app/nlp/samples.py\n"
    f"export const STATIC_SAMPLES = {json.dumps(SAMPLE_CONTRACTS, ensure_ascii=False, separators=(',', ':'))};\n",
    encoding="utf-8",
)
print(f"Wrote {out.relative_to(ROOT)} ({out.stat().st_size:,} bytes)")
